		anchorDigest: currentAnchorDigest,
		epoch: currentEpoch,
		genesisAnchorDigest,
		lifecycle: "active" as const,
		objectId,
		profileId,
	});
}

function digest(domain: string, value: Uint8Array): string {
	return hex(hashDomain(domain, value));
}

